using System;using System.IO;using System.Diagnostics;using System.Windows.Forms;class MomentumOriginal{[STAThread]static void Main(){var root=AppDomain.CurrentDomain.BaseDirectory;var log=Path.Combine(root,"launcher.log");try{var python=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".cache","codex-runtimes","codex-primary-runtime","dependencies","python","pythonw.exe");var script=Path.Combine(root,"original_mode.py");File.AppendAllText(log,DateTime.UtcNow.ToString("o")+" starting "+python+Environment.NewLine);var info=new ProcessStartInfo(python,"-I \""+script+"\""){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=root,RedirectStandardError=true,RedirectStandardOutput=true};info.EnvironmentVariables["PYTHONUTF8"]="1";using(var process=Process.Start(info)){File.AppendAllText(log,"pid="+process.Id+Environment.NewLine);var stdout=process.StandardOutput.ReadToEnd();var stderr=process.StandardError.ReadToEnd();process.WaitForExit();File.AppendAllText(log,"exit="+process.ExitCode+Environment.NewLine+stdout+stderr+Environment.NewLine);if(process.ExitCode!=0)MessageBox.Show("原作者介面啟動失敗，已保存診斷："+log+Environment.NewLine+stderr,"原作者基準模式");}}catch(Exception e){File.AppendAllText(log,e.GetType().Name+": "+e.Message+Environment.NewLine);MessageBox.Show(e.Message,"原作者基準模式");}}}